import json
from decimal import Decimal
from pathlib import Path
p=Path('/root/mailer_policy_analysis.json')
d=json.load(open(p), parse_float=Decimal, parse_int=Decimal)
expected_assumptions=['patients_per_medication','fills_per_year_45_day','fills_per_year_90_day','doses_per_fill_45_day','doses_per_fill_90_day','switch_threshold_usd']
print('Assumption keys exact:', list(d['assumptions'].keys()) == expected_assumptions, list(d['assumptions'].keys()))
med_names=[m['medication'] for m in d['medications']]
print('Medications sorted alphabetically:', med_names == sorted(med_names), med_names)
# Check numeric values round to 2 decimals max for currency-ish keys
bad=[]
for m in d['medications']:
    for k,v in m.items():
        if k.endswith('_usd') and isinstance(v, Decimal):
            if v != v.quantize(Decimal('0.01')):
                bad.append((m['medication'], k, str(v)))
for k,v in d['totals'].items():
    if k.endswith('_usd') and isinstance(v, Decimal):
        if v != v.quantize(Decimal('0.01')):
            bad.append(('totals', k, str(v)))
print('Currency values rounded to <=2 decimal places:', not bad)
if bad: print('Bad currency values:', bad)
neq=[(m['medication'], m['annual_drug_cost_45_day_usd'], m['annual_drug_cost_90_day_usd']) for m in d['medications'] if m['annual_drug_cost_45_day_usd'] != m['annual_drug_cost_90_day_usd']]
print('Annual drug 45 == 90 for each medication:', not neq)
if neq: print('Mismatches:', neq)
summary=Path('/root/mailer_policy_summary.md').read_text()
nonempty=[line for line in summary.splitlines() if line.strip()]
print('Summary non-empty lines:', len(nonempty), nonempty)
print('Summary 4-8 non-empty lines:', 4 <= len(nonempty) <= 8)
print('Summary includes required fields:', all(s in summary for s in ['Total 45-day annual margin:', 'Total 90-day annual margin:', 'Absolute margin difference:', 'Decision: keep_45_day']))
